// Change these, then save. Any API that speaks the OpenAI "chat completions"
// format works: OpenAI, a provider with a free tier, or a model on your own
// machine (Ollama: http://localhost:11434/v1). The key is in the credential
// "Events Newsletter Model".
const MODEL_BASE_URL = 'https://api.openai.com/v1'; // without /chat/completions
const MODEL = 'gpt-4o-mini'; // a small model is enough: it only copies events out of text
const JSON_MODE = true; // asks the API for JSON only. Set to false if your server rejects "response_format".
const RETRY_WAIT_SECONDS = 20; // a page whose answer failed (rate limit, bad JSON) is asked once more after this pause
const CHECK_TITLE_ON_PAGE = true; // leave out an event whose title is not in the page text (a guard against invented events)

return [
  {
    json: {
      model_base_url: MODEL_BASE_URL.replace(/\/+$/, ''),
      model: MODEL,
      json_mode: JSON_MODE,
      retry_wait_seconds: RETRY_WAIT_SECONDS,
      check_title_on_page: CHECK_TITLE_ON_PAGE,
      today: $now.toFormat('yyyy-MM-dd'),
    },
  },
];

// One request per page. What comes in: items { source, url, text }.
// Anything that can produce that shape can use this workflow, not only web pages.
const M = $('Model settings').first().json;

const system = [
  'You copy events out of the text of a web page. You answer with JSON only, in this shape:',
  '{"events":[{"title":"...","date":"YYYY-MM-DD","time":"HH:MM","venue":"...","url":"...","summary":"..."}]}',
  'Rules:',
  '- Only events that are on the page. Never add or guess an event.',
  '- title: as written on the page.',
  '- date: the day the event starts. When the page gives no year, use the next such day on or after today.',
  '- time: start time in 24-hour HH:MM, or null when the page gives none.',
  '- venue: the place as written, or null.',
  '- url: the address of the event\'s own page when the text gives one in [brackets], or null.',
  '- summary: one plain sentence of at most 160 characters taken from the page, or null.',
  '- An event without a date: date is null.',
  '- No events on the page: {"events":[]}',
].join('\n');

return $('Pages in')
  .all()
  .filter((item) => item.json.ok !== false && typeof item.json.text === 'string' && item.json.text.trim() !== '')
  .map((item) => {
    const { source, url, text } = item.json;
    return {
      json: {
        source: String(source ?? url ?? 'page'),
        url: String(url ?? ''),
        text,
        request: {
          model: M.model,
          messages: [
            { role: 'system', content: system },
            { role: 'user', content: `Source: ${source}\nPage address: ${url}\nToday: ${M.today}\n\nPage text:\n${text}` },
          ],
          ...(M.json_mode ? { response_format: { type: 'json_object' } } : {}),
        },
      },
    };
  });

// One answer per page, in the same order as they were asked. An answer that
// is not usable JSON is repaired when that is safe (code fences, text around
// the JSON, a comma before a closing bracket). Otherwise the page is marked
// for one more try.
const pages = $('Build prompt').all();

function events(content) {
  const attempts = [];
  const text = String(content ?? '').trim();
  attempts.push(text);
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(text)?.[1];
  if (fenced) attempts.push(fenced.trim());
  const from = (fenced ?? text).search(/[{[]/);
  const to = Math.max((fenced ?? text).lastIndexOf('}'), (fenced ?? text).lastIndexOf(']'));
  if (from !== -1 && to > from) {
    const inner = (fenced ?? text).slice(from, to + 1);
    attempts.push(inner, inner.replace(/,\s*([}\]])/g, '$1'));
  }
  for (const attempt of attempts) {
    try {
      const value = JSON.parse(attempt);
      if (Array.isArray(value)) return value;
      if (value && Array.isArray(value.events)) return value.events;
    } catch {
      /* try the next one */
    }
  }
  return null;
}

return $input.all().map((item, index) => {
  const page = pages[index].json;
  const status = item.json.statusCode;
  let body = item.json.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      body = null;
    }
  }
  const usage = body?.usage ?? {};
  const out = {
    source: page.source,
    url: page.url,
    page_index: page.page_index ?? index,
    events: null,
    failure: null,
    prompt_tokens: Number(usage.prompt_tokens) || 0,
    completion_tokens: Number(usage.completion_tokens) || 0,
  };
  if (status === 200) {
    out.events = events(body?.choices?.[0]?.message?.content);
    if (out.events === null) out.failure = 'the model answer was not usable JSON';
  } else if (status === 429) {
    // Some providers also use 429 for a used-up quota, so pass their own words on.
    out.failure = `the model API said "too many requests" (HTTP 429)${body?.error?.message ? `: ${String(body.error.message).slice(0, 120)}` : ''}`;
  } else if (status === undefined) {
    out.failure = `the model API could not be reached (${String(item.json.error?.message ?? item.json.error ?? 'no answer').slice(0, 120)})`;
  } else {
    out.failure = `the model API answered HTTP ${status}${body?.error?.message ? `: ${String(body.error.message).slice(0, 120)}` : ''}`;
  }
  return { json: out };
});

// The pages whose first answer failed, with the same request.
const pages = $('Build prompt').all();
return $('Read answers')
  .all()
  .filter((item) => item.json.events === null)
  .map((item) => ({ json: { ...pages[item.json.page_index].json, page_index: item.json.page_index } }));

// One answer per page, in the same order as they were asked. An answer that
// is not usable JSON is repaired when that is safe (code fences, text around
// the JSON, a comma before a closing bracket). Otherwise the page is marked
// for one more try.
const pages = $('Retry list').all();

function events(content) {
